#!/usr/bin/env python3
import os
import re
from pathlib import Path

# Keywords for each category
CATEGORIES = {
    'LLM': [
        'language model', 'large language model', 'llm', 'transformer', 'gpt',
        'bert', 'token', 'tokenization', 'attention mechanism', 'nlp',
        'natural language processing', 'text generation', 'prompt', 'chatbot',
        'instruction tuning', 'rlhf', 'language modeling', 'fine-tuning',
        'decoder', 'encoder', 'pretraining', 'pretrain', 'emergent abilities',
        'in-context learning', 'few-shot', 'zero-shot', 'context window'
    ],
    'trapped_ion_and_qc': [
        'trapped ion', 'quantum computing', 'quantum computer', 'qubit',
        'ion trap', 'quantum gate', 'quantum algorithm', 'quantum error',
        'quantum circuit', 'quantum state', 'quantum mechanics', 'decoherence',
        'entanglement', 'coherence time', 'gate fidelity', 'laser cooling',
        'atomic clock', 'quantum simulation', 'quantum supremacy', 'quantum advantage'
    ],
    'black_hole': [
        'black hole', 'event horizon', 'gravitational wave', 'singularity',
        'schwarzschild', 'hawking radiation', 'ergosphere', 'accretion disk',
        'relativity', 'general relativity', 'spacetime', 'metric',
        'penrose process', 'kerr black hole', 'black hole thermodynamics',
        'gravitational lensing', 'astrophysical black hole', 'supermassive'
    ],
    'DNA': [
        'dna', 'genome', 'gene', 'genetic', 'crispr', 'rna', 'nucleotide',
        'sequence', 'genomics', 'proteomics', 'molecular biology', 'chromosome',
        'mutation', 'heredity', 'double helix', 'base pair', 'transcription',
        'translation', 'protein synthesis', 'biotechnology', 'genetic engineering'
    ],
    'music_history': [
        'music', 'musical', 'composer', 'symphony', 'orchestra', 'classical',
        'baroque', 'romantic', 'renaissance', 'opera', 'sonata', 'concerto',
        'musicology', 'ethnomusicology', 'music history', 'instrument',
        'chamber music', 'folk music', 'historical music', 'period music',
        'counterpoint', 'harmony', 'melody', 'bach', 'mozart', 'beethoven'
    ]
}

def extract_text_from_pdf(filepath):
    """Extract text from PDF file"""
    try:
        with open(filepath, 'rb') as f:
            reader = PyPDF2.PdfReader(f)
            text = ''
            for page in reader.pages[:5]:  # First 5 pages should be enough
                text += page.extract_text() or ''
            return text.lower()
    except Exception as e:
        return ''

def extract_text_from_docx(filepath):
    """Extract text from DOCX file"""
    try:
        from docx import Document
        doc = Document(filepath)
        text = ''
        for para in doc.paragraphs:
            text += para.text + ' '
        return text.lower()
    except Exception as e:
        return ''

def extract_text_from_pptx(filepath):
    """Extract text from PPTX file"""
    try:
        from pptx import Presentation
        prs = Presentation(filepath)
        text = ''
        for slide in prs.slides:
            for shape in slide.shapes:
                if hasattr(shape, 'text'):
                    text += shape.text + ' '
        return text.lower()
    except Exception as e:
        return ''

def categorize_file(filepath):
    """Determine category for a file based on its content"""
    ext = Path(filepath).suffix.lower()

    if ext == '.pdf':
        text = extract_text_from_pdf(filepath)
    elif ext == '.docx':
        text = extract_text_from_docx(filepath)
    elif ext == '.pptx':
        text = extract_text_from_pptx(filepath)
    else:
        return None

    if not text:
        return None

    # Count keyword matches for each category
    scores = {}
    for category, keywords in CATEGORIES.items():
        score = 0
        for keyword in keywords:
            score += len(re.findall(r'\b' + re.escape(keyword) + r'\b', text))
        scores[category] = score

    # Find the category with highest score
    max_score = max(scores.values()) if scores else 0
    if max_score > 0:
        for category, score in scores.items():
            if score == max_score:
                return category

    return None

def main():
    files_dir = '/root/papers/all'
    files = [f for f in os.listdir(files_dir) if f.endswith(('.pdf', '.docx', '.pptx'))]

    results = {}
    for f in files:
        filepath = os.path.join(files_dir, f)
        category = categorize_file(filepath)
        results[f] = category
        print(f"{f}: {category}")

    # Summary
    print("\n--- Summary ---")
    for cat in CATEGORIES.keys():
        count = sum(1 for c in results.values() if c == cat)
        print(f"{cat}: {count} files")

    unmapped = sum(1 for c in results.values() if c is None)
    print(f"Unmapped: {unmapped} files")

if __name__ == '__main__':
    main()

